import cards from './content.json';
import {diagram,images,canVisual,picturePoints,scenePoints} from './visuals.js';
import {mountViewer,currentViewer,disposeView} from './viewer.js';
const byId=Object.fromEntries(cards.map(c=>[c.id,c]));
const units={10:{name:'Muscle anatomy',short:'Muscles',icon:'◒',color:'#a46057',wash:'#f5e6df'},11:{name:'Muscle tissue',short:'Muscle tissue',icon:'▥',color:'#9374a9',wash:'#f0e9f5'},12:{name:'Nervous tissue',short:'Neurons',icon:'⌘',color:'#488c9b',wash:'#e1f0f2'},13:{name:'Central nervous system',short:'Brain & cord',icon:'◉',color:'#a28547',wash:'#f4eedc'},14:{name:'Peripheral & autonomic',short:'PNS & ANS',icon:'⇄',color:'#468573',wash:'#e3f0e9'}};
const KEY='anatomy-practical-2-v1';
const initial=()=>({version:1,settings:{exam:'',minutes:45},studied:{},stats:{},history:[],photos:[]});
let state=initial(),storageOK=true;
try{const raw=localStorage.getItem(KEY);if(raw)state=validate(JSON.parse(raw));localStorage.setItem(KEY,JSON.stringify(state))}catch{storageOK=false}
let page='dashboard',unit=10,selected='deltoid',query='',region='',labels=true,session=null,timer=null,pendingPhoto=null,viewEpoch=0;
let lastResults=null;
const root=document.getElementById('app');
const e=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const button=(text,act,cls='',extra='')=>`<button class="btn ${cls}" data-act="${act}" ${extra}>${text}</button>`;
const shuffle=a=>[...a].sort(()=>Math.random()-.5);
const day=()=>new Date().toLocaleDateString('en-CA');
function validate(d){if(d?.version!==1||!d.stats||typeof d.stats!=='object')throw Error('This is not an Anatomy Practical 2 backup.');const n=initial();n.settings.exam=/^\d{4}-\d{2}-\d{2}$/.test(d.settings?.exam||'')?d.settings.exam:'';n.settings.minutes=Math.max(10,Math.min(180,Number(d.settings?.minutes)||45));for(const[k,v]of Object.entries(d.studied||{}))if(byId[k])n.studied[k]=Boolean(v);for(const[k,v]of Object.entries(d.stats)){const [id,skill]=k.split(':');if(!byId[id]||!['identify','function'].includes(skill)||!Array.isArray(v.events))continue;n.stats[k]={events:v.events.filter(x=>['correct','incorrect','unsure'].includes(x.result)&&typeof x.date==='string'&&Number.isFinite(x.time)).slice(-100).map(x=>({result:x.result,date:x.date,time:x.time,hint:!!x.hint})),due:Number(v.due)||0};}n.history=Array.isArray(d.history)?d.history.filter(x=>typeof x.id==='string'&&Number.isFinite(x.total)&&Number.isFinite(x.correct)).slice(-100).map(x=>({id:x.id,date:String(x.date||''),total:x.total,correct:x.correct,pending:Number(x.pending)||0,mode:x.mode==='mock'?'mock':'practice'})):[];n.photos=Array.isArray(d.photos)?d.photos.filter(x=>byId[x.card]&&/^data:image\/(png|jpeg|webp);base64,/.test(x.src||'')&&Number.isFinite(x.x)&&Number.isFinite(x.y)).map(x=>({id:String(x.id),card:x.card,src:x.src,x:Math.max(0,Math.min(1,x.x)),y:Math.max(0,Math.min(1,x.y))})):[];return n}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true}catch{storageOK=false;toast('Progress is in memory only. Export a backup to keep this session.')}updateStorage()}
function updateStorage(){const x=document.querySelector('.storage-warning');if(!storageOK&&!x){root.insertAdjacentHTML('afterbegin','<div class="storage-warning">Browser storage is unavailable or full. Progress will not persist; export a backup before closing.</div>')}else if(storageOK&&x)x.remove()}
function toast(msg){document.querySelector('.toast')?.remove();const t=document.createElement('div');t.className='toast';t.role='status';t.textContent=msg;document.body.append(t);setTimeout(()=>t.remove(),5000)}
function getStat(id,skill){return state.stats[id+':'+skill]||{events:[],due:0}}
function mastered(id,skill){const st=getStat(id,skill),a=st.events;if(a.length<2)return false;const tail=a.slice(-4);if(tail.at(-1).result!=='correct')return false;const lastBad=a.findLastIndex(x=>x.result!=='correct');return new Set(a.slice(lastBad+1).filter(x=>!x.hint).map(x=>x.date)).size>=2}
function record(q,result){if(q.saved)return;const st=getStat(q.card.id,q.skill);st.events.push({result,date:day(),time:Date.now(),hint:!!q.hint});const days=new Set(st.events.filter(x=>x.result==='correct'&&!x.hint).map(x=>x.date)).size;st.due=Date.now()+(result==='correct'?[1,3,7][Math.max(0,Math.min(2,days-1))]*86400000:result==='unsure'?600000:0);state.stats[q.card.id+':'+q.skill]=st;q.saved=true;state.studied[q.card.id]=true;save()}
function dueItems(){return Object.entries(state.stats).filter(([k,v])=>v.events.length&&v.due<=Date.now()).map(([k,v])=>({card:byId[k.split(':')[0]],skill:k.split(':')[1],st:v})).filter(x=>x.card)}
function weakItems(){return Object.entries(state.stats).filter(([k,v])=>v.events.length&&(v.events.at(-1).result!=='correct'||v.due<=Date.now())).map(([k,v])=>({card:byId[k.split(':')[0]],skill:k.split(':')[1],st:v})).filter(x=>x.card)}
function allEvents(skill){return Object.entries(state.stats).filter(([k])=>!skill||k.endsWith(':'+skill)).flatMap(([k,s])=>s.events)}
function accuracy(skill){const a=allEvents(skill);return a.length?Math.round(a.filter(x=>x.result==='correct').length/a.length*100)+'%':'—'}
function daysLeft(){if(!state.settings.exam)return null;return Math.ceil((new Date(state.settings.exam+'T23:59:59')-new Date())/86400000)}
function nav(name){if(session&&session.stage!=='results'&&page==='quiz'&&!confirm('Leave this practice session? Completed practice answers are saved; unfinished mock answers will be discarded.'))return;clearInterval(timer);if(name!=='quiz')session=null;page=name;query='';region='';render()}
function shell(title,body){viewEpoch++;disposeView();const due=dueItems().length;const navs=[['dashboard','⌂','Dashboard'],['atlas','◈','3D reference'],['learn','▤','Learn'],['practice','✎','Practice'],['mock','◷','Mock practical'],['review','↺','Review mistakes']];root.innerHTML=`<div class="app"><aside class="sidebar"><div class="brand"><span class="brand-mark">a.</span><div><strong>Anatomy</strong><small>PRACTICAL 02</small></div></div><div class="nav-caption">YOUR STUDY SPACE</div><nav>${navs.map(([id,icon,name])=>`<button class="nav-item ${page===id||(page==='quiz'&&session?.mode===(id==='mock'?'mock':id==='practice'?'practice':'none'))?'active':''}" data-act="nav" data-page="${id}"><span class="ico" aria-hidden="true">${icon}</span>${name}${id==='review'&&due?`<span class="nav-badge">${due}</span>`:''}</button>`).join('')}</nav><div class="nav-foot"><div class="scope-note"><span>✓</span><span>Built around your study guide<br>Units 10–14 only</span></div><button class="nav-item" data-act="settings"><span class="ico" aria-hidden="true">⚙</span>Settings & backup</button><button class="nav-item" data-act="sources"><span class="ico" aria-hidden="true">ⓘ</span>Scope & sources</button><p style="margin:16px 13px 0">BIO 270 · Practical 2</p></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">BIO 270 <span style="margin:0 10px">/</span> Practical 2 <span style="margin:0 10px">/</span> <strong>${title}</strong></div><div class="top-actions"><button class="date-badge" data-act="settings">${daysLeft()===null?'◷ Set exam date':daysLeft()<0?'Exam date passed':daysLeft()+' days to your practical'}</button><span class="avatar">EA</span><button class="link-button" data-act="settings" aria-label="Settings">⚙</button></div></header><main class="content" id="main">${body}</main></div></div>`;updateStorage()}
function head(title,desc,action=''){return `<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function metric(label,value,note){return `<div class="metric"><div class="metric-label">${label}</div><strong>${value}</strong><small>${note}</small></div>`}
function render(){if(page==='dashboard')dashboard();else if(page==='learn'||page==='atlas')learn();else if(page==='practice'||page==='mock')setup();else if(page==='review')review();else if(page==='quiz')renderQuiz()}
function dashboard(){const studied=cards.filter(c=>state.studied[c.id]).length;const masteredCount=cards.filter(c=>mastered(c.id,'identify')&&(!c.action||mastered(c.id,'function'))).length;const left=daysLeft()??21;const phase=left>14?1:left>7?2:3;const recent=state.history.slice(-3).reverse();shell('Dashboard',head('Your practical, one session at a time.','Explore the anatomy. Recall it. Come back stronger.')+`<section class="hero"><div class="hero-copy"><div class="eyebrow">BIO 270 · PRACTICAL 02</div><h2>Build confidence.<br>One structure at a time.</h2><p>A focused study space for the muscles, tissues and nervous system on your exam guide.</p><div class="hero-buttons">${button('Start today’s practice <span>→</span>','daily','primary')}${button('Explore 3D','open-atlas','ghost')}</div></div><div class="hero-visual"><div class="model-host" id="hero-model"></div><span class="float-tag">26 required muscles & groups</span><span class="model-caption">Real anatomy · Drag to rotate</span></div></section><div class="metrics">${metric('Topics explored',studied+' / '+cards.length,'Across all five units')}${metric('Identification',accuracy('identify'),'Accuracy from scored answers')}${metric('Actions & functions',accuracy('function'),'Tracked separately')}${metric('Due for review',dueItems().length,'Short sessions build recall')}</div><div class="section-row"><h2>Your five study units</h2><span class="small muted">${masteredCount} topics mastered across days</span></div><section class="unit-grid">${Object.entries(units).map(([u,d])=>{const a=cards.filter(c=>c.unit==u),n=a.filter(c=>state.studied[c.id]).length;return `<button class="unit-card" data-act="unit" data-unit="${u}" style="--color:${d.color};--wash:${d.wash}"><div class="unit-icon">${d.icon}</div><small>Unit ${u}</small><h3>${d.name}</h3><div class="progress-track"><div class="progress-fill" style="width:${n/a.length*100}%;background:${d.color}"></div></div><div class="unit-meta"><span>${n}/${a.length} explored</span><span>↗</span></div></button>`}).join('')}</section><div class="bottom-grid"><section class="panel"><div class="section-row" style="margin:0"><h3>Your study rhythm</h3><span class="badge">${state.settings.minutes} min / day</span></div>${[[1,'Cover the guide','Explore each unit and finish with a few recall questions.'],[2,'Mix and retrieve','Change views, recall actions, and revisit uncertain answers.'],[3,'Rehearse the practical','Use mixed stations and focus on remaining weak areas.']].map(([i,t,d])=>`<div class="plan-row ${i===phase?'active':''}"><span class="plan-num">${i}</span><div><strong>Week ${i} · ${t}</strong><p>${d}</p></div></div>`).join('')}</section><section class="panel"><h3>Recent sessions</h3>${recent.length?recent.map(r=>`<div class="plan-row"><span class="plan-num">${r.mode==='mock'?'◷':'✓'}</span><div style="flex:1"><strong>${r.mode==='mock'?'Mock practical':'Practice session'}</strong><p>${e(r.date)} · ${r.total} stations</p></div><span class="badge">${r.pending?r.pending+' to score':Math.round(r.correct/Math.max(1,r.total)*100)+'%'}</span></div>`).join(''):'<div class="empty"><strong>Your first session starts here.</strong><p class="small">Practice results will appear here.<br>Every score comes from your answers.</p></div>'}${button('Build a mock practical','open-mock','ghost small')}</section></div>`);mountViewer(document.getElementById('hero-model'),{selected:'deltoid',overview:true,preserveOnPick:true,onPick:id=>openCard(id,'atlas')})}
function openCard(id,dest='learn'){if(!byId[id])return;selected=id;unit=byId[id].unit;page=dest;query='';region='';render()}
function filtered(){return cards.filter(c=>(page==='atlas'?c.scene==='muscle':c.unit===unit)&&(!query||[c.name,...c.aliases].join(' ').toLowerCase().includes(query.toLowerCase()))&&(!region||c.region===region))}
function listMarkup(){const a=filtered();return a.length?a.map(c=>`<button class="card-row ${c.id===selected?'selected':''}" data-act="select-card" data-id="${c.id}">${e(c.name)}<small>${page==='atlas'?e(c.region):(c.action?'Identification + action/function':'Identification / vocabulary')}${state.studied[c.id]?' · Viewed':''}</small></button>`).join(''):'<div class="empty small">No matching study-guide terms.</div>'}
function renderList(){const el=document.getElementById('catalog-items');if(el)el.innerHTML=listMarkup();const n=document.getElementById('catalog-count');if(n)n.textContent=filtered().length+' study-guide entries'}
function viewerTools(){return `<div class="viewer-tools">${['front','back','left','right'].map(v=>button(v[0].toUpperCase()+v.slice(1),'view','small',`data-view="${v}"`)).join('')}${button('Full body','view','small','data-view="full"')}${button('Focus muscle','focus-muscle','small')}${button('Reset','view','small','data-view="reset"')}${button('+','zoom-in','small','aria-label="Zoom in"')}${button('−','zoom-out','small','aria-label="Zoom out"')}${button('Deep view','deep','small')}${button('Isolate','isolate','small')}<span class="hint">Drag · Rotate / Right-drag · Pan</span></div><div class="anatomy-context-note"><span class="context-dot selected"></span>Selected muscle <span class="context-dot reference"></span><span>Surrounding anatomy: reference only · not clickable or assessed</span></div>`}
function studyDetail(c){return `<article class="study-card"><div class="study-card-head"><div><div class="eyebrow">Unit ${c.unit} · ${e(units[c.unit].short)}</div><h2>${e(c.name)}</h2></div>${button(labels?'Hide label':'Show label','labels','small')}</div><div class="visual-wrap" id="study-visual">${c.scene==='muscle'?'<div class="model-host" id="study-model"></div>':diagram(c,{learn:labels})}${labels?`<span class="selection-label">${e(c.name)}</span>`:''}</div>${c.scene==='muscle'?viewerTools():`<div class="viewer-tools">${button('Alternate view','alternate','small',picturePoints.sheep[c.id]||['skeletal','cardiac','smooth'].includes(c.scene)?'':'disabled')}${button('My lab photos','photos','small',`data-id="${c.id}"`)}</div>`}<div class="study-card-body"><div class="detail-label">Identify it</div><p>${e(c.description)}</p>${c.action?`<div class="detail-label">${c.unit===10?'Main action':'Function / effect'}</div><p>${e(c.action)}</p>`:''}<div class="callout"><strong>Look for this:</strong> ${e(c.clue)}</div><div class="badge-row"><span class="badge ${mastered(c.id,'identify')?'':'neutral'}">Identification: ${mastered(c.id,'identify')?'mastered':getStat(c.id,'identify').events.length+' attempts'}</span>${c.action?`<span class="badge ${mastered(c.id,'function')?'':'neutral'}">Action/function: ${mastered(c.id,'function')?'mastered':getStat(c.id,'function').events.length+' attempts'}</span>`:''}</div><div class="source">${e(c.objective)}<br>${e(c.source)}</div></div><div class="card-actions">${button(state.studied[c.id]?'✓ Explored':'Mark explored','studied','',`data-id="${c.id}"`)}<div style="display:flex;gap:8px">${button('Practice this','practice-card','primary',`data-id="${c.id}"`)}${button('Next →','next-card')}</div></div></article>`}
function learn(){if(page==='atlas'&&byId[selected]?.scene!=='muscle'){selected='deltoid';unit=10}if(!byId[selected]||byId[selected].unit!==unit){selected=cards.find(c=>c.unit===unit).id}const c=byId[selected];shell(page==='atlas'?'3D reference':'Learn',head(page==='atlas'?'Explore the required muscles.':'Learn the anatomy.','Select a structure, study the visual, then recall it without labels.',button('Add lab photo','photos','',`data-id="${c.id}"`))+(page==='learn'?`<div class="study-tabs">${Object.entries(units).map(([u,d])=>`<button data-act="unit" data-unit="${u}" class="${unit==u?'active':''}">${u} · ${d.short}</button>`).join('')}</div>`:'')+`<div class="${page==='atlas'?'atlas':'learn'}-layout"><aside class="catalog"><div class="catalog-top"><input id="search" class="field" type="search" placeholder="Search ${page==='atlas'?'26 muscles':'this unit'}…" value="${e(query)}" aria-label="Search structures"/>${unit===10?`<select id="region" class="field" aria-label="Body region"><option value="">All regions</option>${['Head and neck','Trunk','Upper limb','Lower limb'].map(x=>`<option ${region===x?'selected':''}>${x}</option>`).join('')}</select>`:''}<p class="catalog-count" id="catalog-count">${filtered().length} study-guide entries</p></div><div class="catalog-items" id="catalog-items">${listMarkup()}</div></aside><div id="study-detail">${studyDetail(c)}</div></div><p class="footer-note">3D anatomy: Z-Anatomy / BodyParts3D · See Scope & sources for licenses · Only study-guide muscles are selectable; surrounding anatomy is reference only.</p>`);if(c.scene==='muscle')mountViewer(document.getElementById('study-model'),{selected:c.id,viewKey:'study',preserveOnPick:true,onPick:id=>{selected=id;render()},fallback:images['fallback_'+c.id]})}
function review(){const a=weakItems();shell('Review mistakes',head('Give the difficult ones another look.','Incorrect, uncertain, and due answers appear here.',button('Review this queue','review-start','primary',a.length?'':'disabled'))+`<div class="metrics">${metric('Due now',dueItems().length,'Ready for another retrieval')}${metric('Needs review',a.length,'Tracked by structure and skill')}${metric('Identification',accuracy('identify'),'All scored attempts')}${metric('Actions & functions',accuracy('function'),'All scored attempts')}</div><div class="review-list">${a.length?a.sort((a,b)=>a.st.due-b.st.due).map(x=>`<div class="review-item"><span class="unit-icon" style="--wash:${units[x.card.unit].wash};--color:${units[x.card.unit].color};margin:0">${units[x.card.unit].icon}</span><div class="grow"><h3>${e(x.card.name)}</h3><p>Unit ${x.card.unit} · ${x.skill==='identify'?'Identification':'Action/function'} · Last response: ${e(x.st.events.at(-1).result)}</p></div>${button('Review','review-one','small',`data-id="${x.card.id}" data-skill="${x.skill}"`)}</div>`).join(''):'<section class="panel empty"><strong>Your review queue is clear.</strong><p>Complete practice questions to discover what needs another look.</p><div class="spacer"></div>'+button('Start practice','open-practice','primary')+'</section>'}</div>`)}
function setup(){const mock=page==='mock';shell(mock?'Mock practical':'Practice',head(mock?'Rehearse the real thing.':'Choose how you want to practice.',mock?'Mixed stations, optional timing, feedback after submission.':'Start with recall, then check your answer and revisit it later.')+`<div class="setup-grid"><section class="panel"><h3>Build your ${mock?'practical':'session'}</h3><form id="session-form"><div class="form-row"><label for="practice-mode">Question mode</label><select id="practice-mode" class="field"><option value="mixed">Mixed identification + actions/functions</option value="identify">Identify a tagged structure</option><option value="function">Recall actions and functions</option><option value="find">Find the named structure</option><option value="match">Match an action/function to its name</option><option value="sequence">Sequence a spinal reflex arc</option></select></div><div class="form-row"><label for="answer-format">Answer format</label><select class="field" id="answer-format"><option value="short">Short answer / self-check</option><option value="mc">Multiple choice (identification)</option></select><p class="help">Open-ended actions use a model answer and your self-assessment. Find and sequence use interactive answers.</p></div><div class="two-fields"><div class="form-row"><label for="question-count">Stations</label><input class="field" id="question-count" type="number" min="1" max="100" value="${mock?30:12}" required/></div><div class="form-row"><label for="station-time">Seconds per station</label><input class="field" id="station-time" type="number" min="0" max="600" value="${mock?60:0}" required/><p class="help">0 = untimed</p></div></div><div class="form-label">Units & relative weights</div><p class="small muted">Weights guide question distribution; they do not represent confirmed exam percentages.</p><div class="check-grid">${Object.entries(units).map(([u,d])=>`<label class="check-row"><input type="checkbox" name="units" value="${u}" checked/>${u} · ${d.short}<input class="field unit-weight" data-unit="${u}" type="number" min="1" max="10" value="1" aria-label="Unit ${u} weight"/></label>`).join('')}</div><button class="btn primary" type="submit">Start ${mock?'mock practical':'practice'} →</button></form></section><section><div class="panel"><div class="eyebrow">Study guide first</div><h3 style="margin-top:12px">Practice exactly what is required.</h3><p class="small muted">All questions connect to a listed term or learning objective. Your workbook supplies the supporting visuals and explanations.</p><div class="callout">Muscle names and actions are scored separately. Brain identification does not become an extra brain-function quiz.</div><p class="small muted">Mastery requires successful recall on different days. One good session is a useful start.</p></div><div class="panel" style="margin-top:18px"><h3>A simple session</h3><div class="plan-row"><span class="plan-num">1</span><div><strong>Attempt the answer</strong><p>Recall before revealing the label or explanation.</p></div></div><div class="plan-row"><span class="plan-num">2</span><div><strong>Check the details</strong><p>Notice the feature that distinguishes the structure.</p></div></div><div class="plan-row"><span class="plan-num">3</span><div><strong>Return later</strong><p>Your uncertain answers enter the review queue.</p></div></div></div></section></div>`)}
const reflexSteps=['Receptor detects the stimulus','Sensory neuron carries input to the CNS','Integration occurs in the CNS','Motor neuron carries output','Effector produces the response'];
function canFind(c){if(c.scene==='muscle')return !['iliopsoas','brachialis','erector_spinae','internal_oblique','semimembranosus'].includes(c.id);return !!(picturePoints[c.scene]?.[c.id]||scenePoints[c.scene]?.[c.id])&&!['meninges','reflex_arc','muscle_myelin'].includes(c.id)}
function makeQuestion(card,skill='identify',format='short',kind=''){const q={card,skill,format,kind:kind||skill,response:'',result:null,saved:false,hint:false};if(q.kind==='sequence'){q.order=shuffle(reflexSteps);q.skill='function'}if(q.kind==='match'||format==='mc'&&skill==='identify'){q.options=shuffle([card,...shuffle(cards.filter(c=>c.unit===card.unit&&c.id!==card.id&&(q.kind!=='match'||c.action))).slice(0,3)]);q.format='mc'}q.variant=Math.random()<.45?'alternate':'';if(card.scene==='brain'&&picturePoints.sheep[card.id]&&Math.random()<.4)q.variant='specimen';return q}
function makePool(us,mode,format){const a=cards.filter(c=>us.includes(c.unit));let pool=[];for(const c of a){if(mode==='sequence'){if(c.id==='reflex_arc')pool.push(makeQuestion(c,'function',format,'sequence'));continue}if(mode==='find'){if(canFind(c))pool.push(makeQuestion(c,'identify',format,'find'));continue}if(mode==='match'){if(c.action&&c.id!=='reflex_arc')pool.push(makeQuestion(c,'function','mc','match'));continue}if(mode!=='function'&&c.scene!=='ans'&&c.id!=='reflex_arc')pool.push(makeQuestion(c,'identify',format));if(mode!=='identify'&&c.action)pool.push(makeQuestion(c,'function','short',c.id==='reflex_arc'?'sequence':'function'))}return pool}
function weightedPick(pool,n,weights){const result=[],buckets={};for(const q of shuffle(pool))(buckets[q.card.unit]??=[]).push(q);const us=shuffle(Object.keys(buckets));for(const u of us){if(result.length<n&&buckets[u].length)result.push(buckets[u].pop())}while(result.length<n){const available=Object.keys(buckets).filter(u=>buckets[u].length);if(!available.length)break;const total=available.reduce((s,u)=>s+(weights[u]||1),0);let r=Math.random()*total,chosen=available[0];for(const u of available){r-=weights[u]||1;if(r<=0){chosen=u;break}}result.push(buckets[chosen].pop())}return shuffle(result)}
function startSession(qs,mode='practice',seconds=0){if(!qs.length){toast('No questions match this combination. Choose another unit or mode.');return}clearInterval(timer);session={id:'s'+Date.now(),questions:qs,index:0,mode,seconds,stage:'answer',deadline:0,historySaved:false};page='quiz';renderQuiz()}
function startFromForm(){const us=[...document.querySelectorAll('input[name="units"]:checked')].map(x=>Number(x.value));if(!us.length){toast('Select at least one unit.');return}const mode=document.getElementById('practice-mode').value,format=document.getElementById('answer-format').value,n=Math.max(1,Math.min(100,Number(document.getElementById('question-count').value)||12)),seconds=Math.max(0,Math.min(600,Number(document.getElementById('station-time').value)||0));const weights={};document.querySelectorAll('.unit-weight').forEach(x=>weights[x.dataset.unit]=Math.max(1,Math.min(10,Number(x.value)||1)));const qs=weightedPick(makePool(us,mode,format),n,weights);if(qs.length&&qs.length<n)toast(`This selection has ${qs.length} distinct stations; all are included.`);startSession(qs,page==='mock'?'mock':'practice',seconds)}
function questionPrompt(q){if(q.kind==='sequence')return 'Put the spinal reflex pathway in order.';if(q.kind==='match')return 'Which structure or division matches this action/function?';if(q.kind==='find')return `Find ${q.card.name}.`;if(q.skill==='function')return `${q.card.unit===10?'What are the main actions of':'What are the functions or effects of'} ${q.card.name}?`;if(q.card.id==='synapse')return 'What is the junction between these two cells called?';if(q.card.id==='meninges')return 'What is the collective name for these three coverings?';if(['muscle_fascicle','nerve_fascicle'].includes(q.card.id))return 'Name the tagged bundle of fibers.';if(q.card.id==='myofilaments')return 'What is the collective term for the protein filaments shown?';if(q.card.id==='epithalamus')return 'Name the diencephalic region containing the tagged pineal landmark.';if(q.card.id==='ventricles')return 'Name this cavity or the brain cavity system it belongs to.';if(['skeletal','cardiac','smooth'].includes(q.card.scene))return 'Identify this muscle tissue.';if(!canVisual(q.card))return 'Which study-guide term matches this description?';return q.card.scene==='muscle'?'Identify the highlighted muscle or group.':'Identify the tagged structure.'}
function userPhotoVisual(q){if(!q.photo)return '';const p=q.photo;return `<div class="photo-stage"><img src="${p.src}" alt="Your lab photograph"/><span class="photo-pin" style="left:${p.x*100}%;top:${p.y*100}%"></span></div><p class="visual-caption">Your lab photograph</p>`}
function quizVisual(q){if(q.photo)return userPhotoVisual(q);if(q.card.scene==='muscle'&&q.kind!=='match')return '<div class="model-host" id="quiz-model"></div>';if(q.kind==='match')return `<div class="concept-visual" style="padding:35px"><span class="concept-symbol">⇄</span><p style="color:var(--ink);font-size:19px;line-height:1.5;text-align:center">${e(q.card.action)}</p></div>`;if(!canVisual(q.card)&&q.skill==='identify')return `<div class="concept-visual" style="padding:35px"><span class="concept-symbol">Aa</span><p style="color:var(--ink);font-size:19px;text-align:center">${e(q.card.description)}</p></div>`;return diagram(q.card,{find:q.kind==='find',variant:q.variant})}
function answerUI(q){if(q.kind==='sequence')return `<div id="sequence-list">${q.order.map((s,i)=>`<div class="sequence-item"><strong>${i+1}</strong><span>${e(s)}</span><button data-act="seq-up" data-index="${i}" aria-label="Move step up" ${!i?'disabled':''}>↑</button><button data-act="seq-down" data-index="${i}" aria-label="Move step down" ${i===q.order.length-1?'disabled':''}>↓</button></div>`).join('')}</div>`;if(q.kind==='find')return `<div class="callout" id="selection-status">${q.response?'Selection recorded. You can choose again.':'Select a muscle on the model or a pin in the diagram.'}</div>`;if(q.format==='mc')return `<div id="options">${q.options.map((c,i)=>`<button class="option ${q.response===c.id?'chosen':''}" data-act="option" data-id="${c.id}"><span class="letter">${'ABCD'[i]}</span>${e(c.name)}</button>`).join('')}</div>`;return `<label class="form-label" for="answer">Your answer</label><textarea class="field answer-input" id="answer" placeholder="Recall it before checking…">${e(q.response)}</textarea>`}
function normal(s){return String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\b(muscles?|tissue|group|the|a|an)\b/g,'').replace(/[^a-z0-9]/g,'')}
function distance(a,b){const d=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let old=d[0];d[0]=i;for(let j=1;j<=b.length;j++){const save=d[j];d[j]=Math.min(d[j]+1,d[j-1]+1,old+(a[i-1]!==b[j-1]));old=save}}return d[b.length]}
function checkName(c,s){const raw=String(s).trim();if(!raw)return false;let aliases=[c.name,...c.aliases];if(c.id==='ventricles')aliases.push('lateral ventricle','lateral ventricles');if(c.id==='erector_spinae')aliases.push('erector spinae');if(c.id==='quadriceps')aliases.push('quadriceps','quadriceps femoris');const n=normal(raw),ans=aliases.map(normal);if(ans.includes(n))return true;if(cards.some(other=>other.id!==c.id&&[other.name,...other.aliases].map(normal).includes(n)))return false;return n.length>=6&&ans.some(a=>a.length>=6&&distance(n,a)<=1)}
function capture(){const q=session.questions[session.index];if(q.kind==='sequence')q.response=q.order.join(' → ');else if(document.getElementById('answer'))q.response=document.getElementById('answer').value.trim();return q}
function grade(q){if(q.kind==='sequence')return q.order.every((x,i)=>x===reflexSteps[i])?'correct':'incorrect';if(q.kind==='find'||q.format==='mc')return q.response===q.card.id?'correct':'incorrect';if(q.skill==='function')return q.response?'pending':'incorrect';return checkName(q.card,q.response)?'correct':'incorrect'}
function answerText(q){return q.kind==='sequence'?reflexSteps.join(' → '):q.kind==='match'||q.kind==='find'||q.skill==='identify'?q.card.name:q.card.action}
function responseText(q){return q.kind==='find'||q.format==='mc'?byId[q.response]?.name||'No answer':q.response||'No answer'}
function ratings(index=null){return `<div class="rating-row">${[['correct','I got it'],['incorrect','Needs review'],['unsure','Unsure']].map(([r,t])=>button(t,'rate',r==='correct'?'primary':'',`data-result="${r}" ${index!==null?`data-index="${index}"`:''}`)).join('')}</div>`}
function feedbackMarkup(q){return `<div class="feedback ${q.result==='incorrect'?'incorrect':''}" role="status"><h3>${q.result==='correct'?'✓ Correct':q.result==='pending'?'Compare your answer':q.result==='unsure'?'Marked unsure':'Let’s review this one'}</h3><p><strong>${e(answerText(q))}</strong></p><p>${e(q.skill==='identify'?q.card.clue:q.card.description)}</p>${q.result==='pending'?'<p>Check the main points above, then assess your answer.</p>'+ratings():''}</div><div class="source">${e(q.card.objective)}<br>${e(q.card.source)}</div>`}
function renderQuiz(){if(!session)return nav('practice');if(session.stage==='results')return results();const q=session.questions[session.index];if(!q.photo&&q.kind==='identify'){const a=state.photos.filter(p=>p.card===q.card.id);if(a.length&&Math.random()<.4)q.photo=a[0]}const feedback=session.stage==='feedback';shell(session.mode==='mock'?'Mock practical':'Practice',`<div class="question-top"><div><span class="eyebrow">${session.mode==='mock'?'Mock practical':'Practice session'}</span><p class="small muted">Station ${session.index+1} of ${session.questions.length} · Unit ${q.card.unit} · ${q.skill==='identify'?'Identification':'Action / function'}</p></div><div style="display:flex;align-items:center;gap:20px"><span class="timer" id="timer">${session.seconds?session.seconds+'s':'Untimed'}</span>${button('End session','end-session','small ghost')}</div></div><div class="progress-track" style="margin-bottom:22px"><div class="progress-fill" style="width:${session.index/session.questions.length*100}%"></div></div><div class="quiz-layout"><div class="quiz-visual"><div class="visual-wrap">${quizVisual(q)}</div>${q.card.scene==='muscle'&&!q.photo&&q.kind!=='match'?viewerTools():''}</div><section class="panel"><span class="badge neutral">${q.kind==='sequence'?'Sequence':q.kind==='find'?'Find it':q.kind==='match'?'Match it':q.format==='mc'?'Multiple choice':'Recall first'}</span><h2 class="question-text">${e(questionPrompt(q))}</h2>${feedback?`<p class="small muted">Your answer: ${e(responseText(q))}</p>`:answerUI(q)}${feedback?feedbackMarkup(q):''}${q.hint&&!feedback?`<div class="callout">${e(q.card.clue)}</div>`:''}<div class="quiz-actions">${!feedback?(session.mode==='mock'?'<span class="small muted">Feedback after submission</span>':button('Show hint','hint','ghost small')):''}${feedback?button(session.index===session.questions.length-1?'Finish session':'Next station →','next-question','primary',q.result==='pending'?'disabled':''):button(session.mode==='mock'?(session.index===session.questions.length-1?'Submit practical':'Save & next →'):'Check answer','check-answer','primary')}</div></section></div>`);if(q.card.scene==='muscle'&&!q.photo&&q.kind!=='match'){const myEpoch=viewEpoch;mountViewer(document.getElementById('quiz-model'),{viewKey:q,selected:q.kind==='find'?null:q.card.id,highlight:q.kind!=='find',overview:q.kind==='find',onPick:id=>{if(myEpoch!==viewEpoch||session?.stage!=='answer'||q.kind!=='find')return;q.response=id;document.getElementById('selection-status').textContent='Selection recorded. You can choose again.'},fallback:images['fallback_'+q.card.id]})}clearInterval(timer);if(!feedback&&session.seconds){if(!session.deadline)session.deadline=Date.now()+session.seconds*1000;timer=setInterval(()=>{if(!session||session.stage!=='answer')return;const remaining=Math.max(0,Math.ceil((session.deadline-Date.now())/1000));const t=document.getElementById('timer');if(t){t.textContent=remaining+'s';t.classList.toggle('urgent',remaining<=10)}if(!remaining){clearInterval(timer);checkAnswer()}},250)}}
function checkAnswer(){if(!session||session.stage!=='answer')return;clearInterval(timer);const q=capture();q.result=grade(q);session.deadline=0;if(session.mode==='mock'){if(session.index===session.questions.length-1)finish();else{session.index++;renderQuiz()}}else{session.stage='feedback';if(q.result!=='pending')record(q,q.result);renderQuiz()}}
function nextQuestion(){if(!session)return;if(session.index===session.questions.length-1){finish();return}session.index++;session.stage='answer';session.deadline=0;renderQuiz()}
function finish(){clearInterval(timer);for(const q of session.questions){if(q.result&&q.result!=='pending')record(q,q.result)}session.stage='results';updateHistory();results()}
function updateHistory(){if(!session)return;const completed=session.questions.filter(q=>q.result);const row={id:session.id,date:day(),mode:session.mode,total:completed.length,correct:completed.filter(q=>q.result==='correct').length,pending:completed.filter(q=>q.result==='pending').length};const ix=state.history.findIndex(x=>x.id===session.id);if(ix>=0)state.history[ix]=row;else state.history.push(row);state.history=state.history.slice(-100);save()}
function results(){const qs=session.questions.filter(q=>q.result),correct=qs.filter(q=>q.result==='correct').length,pending=qs.filter(q=>q.result==='pending').length,scored=qs.length-pending;lastResults=session;shell('Session results',head('Here’s what to revisit.',pending?'Use the model answers to assess your open-ended responses.':'Your results are saved. Missed and uncertain answers are in your review queue.',button('Back to dashboard','open-dashboard'))+`<div class="metrics">${metric('Scored accuracy',scored?Math.round(correct/scored*100)+'%':'—',correct+' correct / '+scored+' scored')}${metric('Identification',qs.filter(q=>q.skill==='identify'&&q.result==='correct').length+' / '+qs.filter(q=>q.skill==='identify'&&q.result!=='pending').length,'Independent skill tracking')}${metric('Actions & functions',qs.filter(q=>q.skill==='function'&&q.result==='correct').length+' / '+qs.filter(q=>q.skill==='function'&&q.result!=='pending').length,'Scored responses only')}${metric('To self-assess',pending,'Open-ended responses')}</div><div class="panel"><h3>Station review</h3>${session.questions.map((q,i)=>!q.result?'':`<div class="result-item"><div class="badge-row"><span class="badge ${q.result==='correct'?'':q.result==='pending'?'warn':'neutral'}">${q.result==='pending'?'Self-assess':q.result}</span><span class="small muted">Station ${i+1} · Unit ${q.card.unit} · ${q.skill==='identify'?'Identification':'Action/function'}</span></div><h3 style="margin-top:10px">${e(q.card.name)}</h3><p>Your answer: ${e(responseText(q))}</p><p><strong>Model answer:</strong> ${e(answerText(q))}</p><p>${e(q.card.clue)}</p>${q.result==='pending'?ratings(i):''}<div class="source">${e(q.card.source)}</div></div>`).join('')}</div><div class="section-row">${button('Review missed questions','retry-missed','primary')}${button('New practice session','open-practice')}</div>`)}
function modal(title,body){document.getElementById('modal')?.remove();const el=document.createElement('div');el.id='modal';el.className='modal-backdrop';el.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="${e(title)}"><div class="modal-head"><h2>${title}</h2><button class="close" data-act="close-modal" aria-label="Close">×</button></div>${body}</section>`;document.body.append(el);el.querySelector('button,input')?.focus()}
function settings(){modal('Your study settings',`<div class="two-fields"><div class="form-row"><label for="exam-date">Exam date</label><input id="exam-date" class="field" type="date" value="${e(state.settings.exam)}"/></div><div class="form-row"><label for="daily-minutes">Daily study minutes</label><input id="daily-minutes" class="field" type="number" min="10" max="180" value="${state.settings.minutes}"/></div></div>${button('Save settings','save-settings','primary')}<div class="source"></div><h3>Progress & backup</h3><p>Progress is saved in this browser on this device. Export a backup to transfer it or keep an extra copy. Import replaces the current progress after confirmation.</p><div style="display:flex;gap:10px;flex-wrap:wrap">${button('Export backup','export')}${button('Import backup','import')}<input type="file" id="import-file" accept="application/json,.json" hidden/></div><p>${storageOK?'✓ Browser storage is available.':'Browser storage is unavailable. Export before closing.'}</p><div class="source"></div><h3>Start fresh</h3><p>Reset removes this app’s progress and uploaded lab photos from this browser.</p>${button('Reset all progress','reset','danger')}`)}
function sources(){modal('Exam scope & sources',`<p><strong>Primary scope:</strong> Bio270 Fall 26 — Study Guide for Practical 2, Units 10–14. ${cards.length} cards map to the listed vocabulary and learning objectives. Supporting muscle microanatomy is drawn from the workbook’s relevant model inventories.</p><div class="scope-grid">${Object.entries(units).map(([u,d])=>`<div class="scope-unit"><h3>${u} · ${d.name}</h3><p>${cards.filter(c=>c.unit==u).length} study entries</p><details><summary class="small">See scope list</summary><p>${cards.filter(c=>c.unit==u).map(c=>e(c.name)).join(' · ')}</p></details></div>`).join('')}</div><p>Individual muscle attachments, extra muscles, nerve plexus catalogs, and full action-potential physiology are excluded. Brain structures are assessed for identification, not extra function memorization.</p><h3>3D anatomy</h3><p><a href="https://github.com/LluisV/Z-Anatomy" target="_blank" rel="noopener">Z-Anatomy</a> — models by Gauthier Kervyn and contributors; FBX distribution by Lluís Vinent Juanico. Derived from BodyParts3D, The Database Center for Life Science.</p><p>Models and their adaptations: <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener">CC BY-SA 4.0</a>. The added BodyParts3D 4.0 reference surfaces retain their <a href="https://creativecommons.org/licenses/by-sa/2.1/jp/" target="_blank" rel="noopener">CC BY-SA 2.1 Japan</a> attribution and license. Modifications: world-space transforms applied, selected muscle coverings omitted, mesh simplification, coordinate rounding, study colors, and mapping to the 26 required entries. Non-selectable bones, teeth, cartilage and eye surfaces from BodyParts3D are registered to the muscle reference; tendons and selected connective tissues supply additional context. All 26 entries have mapped geometry. Added surroundings are reference only and are not new exam topics. Simplified, registered surfaces may differ from your lab models and should not be used to memorize precise attachments.</p><h3>Course visuals</h3><p>Muscle photomicrographs: Unit 11, Figures 11.7 and 11.15. Brain views and specimens: Unit 13, Figures 13.6, 13.8 and 13.15. Cranial nerves: Unit 14, Figure 14.3. Surrounding printed labels were masked or cropped. Original schematic study diagrams supplement these figures.</p><p>Workbook excerpts are bundled for your personal study. Their reuse permissions have not been verified for public redistribution. Use licensed replacements before a public release.</p><p>Basic action/effect wording is cross-checked with <a href="https://openstax.org/books/anatomy-and-physiology-2e/pages/11-6-appendicular-muscles-of-the-pelvic-girdle-and-lower-limbs" target="_blank" rel="noopener">OpenStax Anatomy & Physiology 2e, Chapter 11</a> and <a href="https://openstax.org/books/anatomy-and-physiology-2e/pages/15-1-divisions-of-the-autonomic-nervous-system" target="_blank" rel="noopener">Chapter 15</a>. Three.js is MIT licensed.</p><p>Short-answer actions/functions are self-assessed. Clinical tests and detailed physiology outside your guide are not included.</p>`)}
function photos(id=selected){pendingPhoto=null;modal('Add a lab photograph',`<p>Choose a study-guide term, add a photograph, then click the exact structure to place a quiz pin. Use an unlabeled photograph so captions do not give away the answer.</p><div class="form-row"><label for="photo-card">Study-guide term</label><select id="photo-card" class="field">${cards.filter(c=>canVisual(c)).map(c=>`<option value="${c.id}" ${c.id===id?'selected':''}>${c.unit} · ${e(c.name)}</option>`).join('')}</select></div><div class="form-row"><label for="photo-file">Photograph</label><input type="file" id="photo-file" accept="image/png,image/jpeg,image/webp" class="field"/></div><div id="photo-editor"><p class="small muted">PNG, JPEG, or WebP · Choose a clear image of a permitted course model or specimen.</p></div><div class="spacer"></div>${button('Save photo & pin','save-photo','primary','disabled')}<div class="source"></div><h3>Your photographs (${state.photos.length})</h3><div>${state.photos.map(p=>`<div class="plan-row"><span style="flex:1;font-size:12px">${e(byId[p.card].name)}</span>${button('Practice','photo-practice','small',`data-id="${p.id}"`)}${button('Remove','remove-photo','small danger',`data-id="${p.id}"`)}</div>`).join('')||'<p>No photographs added yet.</p>'}</div>`)}
async function loadPhoto(file){if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)){toast('Choose a PNG, JPEG, or WebP photograph.');return}if(file.size>15*1024*1024){toast('Choose a photograph smaller than 15 MB.');return}try{const b=await createImageBitmap(file);const scale=Math.min(1,1000/Math.max(b.width,b.height));const c=document.createElement('canvas');c.width=Math.round(b.width*scale);c.height=Math.round(b.height*scale);c.getContext('2d').drawImage(b,0,0,c.width,c.height);b.close();pendingPhoto={id:'p'+Date.now(),src:c.toDataURL('image/webp',.84),x:null,y:null};document.getElementById('photo-editor').innerHTML=`<div class="upload-stage" id="upload-stage"><img src="${pendingPhoto.src}" alt="Place a pin on your photograph"/></div><p class="small muted">Click the structure to place the pin.</p>`}catch{toast('That image could not be opened.')}}
function closeModal(){document.getElementById('modal')?.remove()}
function exportBackup(){const b=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download='Anatomy_Practical_2_Backup_'+day()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exported.')}
async function importBackup(file){if(!file)return;try{if(file.size>20*1024*1024)throw Error('This backup is larger than expected.');const fresh=validate(JSON.parse(await file.text()));if(!confirm('Replace current progress and lab photos with this backup?'))return;state=fresh;save();closeModal();clearInterval(timer);session=null;page='dashboard';render();toast('Backup imported.')}catch(err){toast(err.message||'The backup could not be read.')}}
function daily(){const n=Math.max(5,Math.min(30,Math.round(state.settings.minutes/3.5))),weak=weakItems();let qs=weak.slice(0,Math.ceil(n*.4)).map(x=>makeQuestion(x.card,x.skill));const used=new Set(qs.map(q=>q.card.id+q.skill));const pool=makePool([10,11,12,13,14],'mixed','short').filter(q=>!used.has(q.card.id+q.skill));const unstudied=pool.filter(q=>!state.studied[q.card.id]);qs.push(...weightedPick(unstudied.length>=n-qs.length?unstudied:pool,n-qs.length,{}));startSession(shuffle(qs))}
function rate(result,index){if(!session)return;const q=session.questions[index??session.index];if(!q||q.result!=='pending')return;q.result=result;record(q,result);if(session.stage==='results'){updateHistory();results()}else renderQuiz()}
function retryMissed(){const old=session||lastResults;if(!old)return;const a=old.questions.filter(q=>q.result&&q.result!=='correct'&&q.result!=='pending').map(q=>makeQuestion(q.card,q.skill,q.format,q.kind));startSession(a)}
function endSession(){if(!session)return;if(!confirm(session.mode==='mock'?'Submit the answers completed so far?':'Finish this practice session now?'))return;if(session.mode==='mock'&&session.stage==='answer'){const q=capture();q.result=grade(q)}finish()}
function selectedPin(id){if(page!=='quiz'||session?.stage!=='answer')return;const q=session.questions[session.index];if(q.kind!=='find')return;q.response=id;document.querySelectorAll('.choice-pin').forEach(p=>p.style.opacity=p.dataset.pin===id?'1':'.45');const msg=document.getElementById('selection-status');if(msg)msg.textContent='Selection recorded. You can choose again.'}
document.addEventListener('click',async ev=>{
 const pin=ev.target.closest('[data-pin]');if(pin)selectedPin(pin.dataset.pin);
 const up=ev.target.closest('#upload-stage');if(up&&pendingPhoto){const r=up.getBoundingClientRect();pendingPhoto.x=(ev.clientX-r.left)/r.width;pendingPhoto.y=(ev.clientY-r.top)/r.height;up.querySelector('.photo-pin')?.remove();up.insertAdjacentHTML('beforeend',`<span class="photo-pin" style="left:${pendingPhoto.x*100}%;top:${pendingPhoto.y*100}%"></span>`);document.querySelector('[data-act="save-photo"]').disabled=false}
 const b=ev.target.closest('[data-act]');if(!b||b.disabled)return;const a=b.dataset.act;
 if(a==='nav')nav(b.dataset.page);
 else if(a==='open-dashboard')nav('dashboard');else if(a==='open-atlas')nav('atlas');else if(a==='open-practice')nav('practice');else if(a==='open-mock')nav('mock');
 else if(a==='settings')settings();else if(a==='sources')sources();else if(a==='close-modal')closeModal();
 else if(a==='unit'){unit=Number(b.dataset.unit);selected=cards.find(c=>c.unit===unit).id;page='learn';query='';region='';render()}
 else if(a==='select-card'){selected=b.dataset.id;render()}
 else if(a==='labels'){labels=!labels;render()}
 else if(a==='studied'){state.studied[b.dataset.id]=true;save();b.textContent='✓ Explored';renderList()}
 else if(a==='next-card'){const a=filtered(),i=a.findIndex(c=>c.id===selected);selected=a[(i+1)%a.length]?.id||selected;render()}
 else if(a==='practice-card'){const c=byId[b.dataset.id];startSession([makeQuestion(c),...(c.action?[makeQuestion(c,'function')]:[])])}
 else if(a==='daily')daily();else if(a==='review-start')startSession(weakItems().map(x=>makeQuestion(x.card,x.skill)));else if(a==='review-one')startSession([makeQuestion(byId[b.dataset.id],b.dataset.skill)]);
 else if(a==='view')currentViewer()?.preset(b.dataset.view);else if(a==='focus-muscle')currentViewer()?.focusSelection();else if(a==='deep'){b.classList.toggle('active',currentViewer()?.toggleDeep())}else if(a==='isolate'){b.classList.toggle('active',currentViewer()?.toggleIsolate())}else if(a==='zoom-in')currentViewer()?.zoom(.8);else if(a==='zoom-out')currentViewer()?.zoom(1.25);
 else if(a==='alternate'){const c=byId[selected];const variant=picturePoints.sheep[c.id]?'specimen':['skeletal','cardiac','smooth'].includes(c.scene)?'alternate':null;if(!variant){toast('This entry currently has one 2D view. Add a lab photo for another.');return}const v=document.getElementById('study-visual');v.innerHTML=diagram(c,{learn:labels,variant:v.dataset.variant?'':variant});v.dataset.variant=v.dataset.variant?'':variant}
 else if(a==='photos')photos(b.dataset.id||selected);else if(a==='save-photo'){if(!pendingPhoto||pendingPhoto.x===null)return;pendingPhoto.card=document.getElementById('photo-card').value;state.photos.push(pendingPhoto);save();closeModal();toast('Photograph and quiz pin saved.')}
 else if(a==='remove-photo'){if(confirm('Remove this lab photograph?')){state.photos=state.photos.filter(p=>p.id!==b.dataset.id);save();photos(selected)}}
 else if(a==='photo-practice'){const p=state.photos.find(x=>x.id===b.dataset.id);if(p){const q=makeQuestion(byId[p.card]);q.photo=p;closeModal();startSession([q])}}
 else if(a==='save-settings'){state.settings.exam=document.getElementById('exam-date').value;state.settings.minutes=Math.max(10,Math.min(180,Number(document.getElementById('daily-minutes').value)||45));save();closeModal();render();toast('Study settings saved.')}
 else if(a==='export')exportBackup();else if(a==='import')document.getElementById('import-file').click();
 else if(a==='reset'){if(confirm('Reset all progress and uploaded photos in this browser? This cannot be undone without a backup.')){state=initial();save();closeModal();clearInterval(timer);session=null;page='dashboard';render();toast('Progress reset.')}}
 else if(a==='option'){if(session?.stage!=='answer')return;const q=session.questions[session.index];q.response=b.dataset.id;document.querySelectorAll('.option').forEach(x=>x.classList.toggle('chosen',x===b))}
 else if(a==='hint'){capture();session.questions[session.index].hint=true;renderQuiz()}
 else if(a==='check-answer')checkAnswer();else if(a==='next-question')nextQuestion();else if(a==='rate')rate(b.dataset.result,b.dataset.index===undefined?null:Number(b.dataset.index));else if(a==='retry-missed')retryMissed();else if(a==='end-session')endSession();
 else if(a==='seq-up'||a==='seq-down'){const q=session.questions[session.index],i=Number(b.dataset.index),j=i+(a==='seq-up'?-1:1);if(j<0||j>=q.order.length)return;[q.order[i],q.order[j]]=[q.order[j],q.order[i]];capture();renderQuiz()}
});
document.addEventListener('input',ev=>{if(ev.target.id==='search'){query=ev.target.value;renderList()}});
document.addEventListener('change',ev=>{if(ev.target.id==='region'){region=ev.target.value;renderList()}if(ev.target.id==='photo-file')loadPhoto(ev.target.files[0]);if(ev.target.id==='import-file')importBackup(ev.target.files[0])});
document.addEventListener('submit',ev=>{if(ev.target.id==='session-form'){ev.preventDefault();startFromForm()}});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape')closeModal();if((ev.key==='Enter'||ev.key===' ')&&ev.target.matches('[data-pin]')){ev.preventDefault();selectedPin(ev.target.dataset.pin)}if(ev.key==='Tab'&&document.getElementById('modal')){const focus=[...document.querySelectorAll('#modal button:not([disabled]),#modal input:not([hidden]),#modal select,#modal summary,#modal a[href]')];if(!focus.length)return;if(ev.shiftKey&&document.activeElement===focus[0]){ev.preventDefault();focus.at(-1).focus()}else if(!ev.shiftKey&&document.activeElement===focus.at(-1)){ev.preventDefault();focus[0].focus()}}});
