window.AnatomyApp={cards,units,getState:()=>JSON.parse(JSON.stringify(state)),getSession:()=>session,getPage:()=>page,openCard,viewer:currentViewer,startSession,makeQuestion,checkName,normal,mastered,validate};
render();
